// Block (composition) — confirmation content arranged inside the Dialog Component.
// Dialog owns open/close/focus behavior and chrome; this Block owns no overlay behavior or look.
import type { ReactNode } from "react";
import {
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../components/Dialog";
import { Button } from "../components/Button";
import "./ConfirmDialog.css";

export interface ConfirmDialogProps {
  /** Control that opens the dialog. */
  trigger: ReactNode;
  /** Dialog heading. */
  title: string;
  /** Supporting confirmation message. */
  message?: ReactNode;
  /** Confirm action label. */
  confirmLabel?: string;
  /** Cancel action label. */
  cancelLabel?: string;
  /** Called when the confirm action is pressed. */
  onConfirm?: () => void;
  /** Existing Button intent used for the confirm action. */
  confirmVariant?: "primary" | "secondary" | "destructive";
  /** Leading status icon (optional) — shown in the dialog header. Pass at `size="1em"`. */
  icon?: ReactNode;
  /** Layout alignment — `center` for an alert-style centered dialog. Default `start`. */
  align?: "start" | "center";
}

export function ConfirmDialog({
  trigger,
  title,
  message,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  onConfirm,
  confirmVariant = "primary",
  icon,
  align,
}: ConfirmDialogProps) {
  return (
    <DialogTrigger>
      {trigger}
      <DialogContent className="sd-confirmdialog" width="small"
        header={
          <DialogHeader icon={icon} align={align}>
            <DialogTitle>{title}</DialogTitle>
            {message && <DialogDescription>{message}</DialogDescription>}
          </DialogHeader>
        }
        footer={
          <DialogFooter layout={align === "center" ? "center" : "end"}>
            <Button size="large" type="button" variant="secondary" slot="close">
              {cancelLabel}
            </Button>
            <Button size="large" type="button" variant={confirmVariant} slot="close" onPress={onConfirm}>
              {confirmLabel}
            </Button>
          </DialogFooter>
        }
      />
    </DialogTrigger>
  );
}

/* ConfirmDialog.css — .sd-confirmdialog (Block)
   Arrangement is handled by Stack; Dialog and Button own all chrome and look.
   This Block defines no tokens and does not reach into Component internals. */
